-- ============================================
-- LUMA — Thème 5 : LONG 2/3 x4 — Gérer une urgence avec la barrière de la langue
-- ============================================


update scenarios set content = '{"characters": {"nurse": "l''infirmière", "patient": "la patiente", "doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Waiting in the ER, you notice a patient nearby speaking a language the staff can''t understand.)", "text_fr": "(En attendant aux urgences, vous remarquez un patient à proximité parlant une langue que le personnel ne comprend pas.)", "choices": [{"text": "(Listen closely to see if you can understand any of it.)", "text_fr": "(Écoute attentivement pour voir si tu comprends quelque chose.)", "next": "n2"}, {"text": "(Approach the nurse to ask if you can help.)", "text_fr": "(Approche l''infirmière pour demander si tu peux aider.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You recognize a few words — it''s a language you studied a little in school.)", "text_fr": "(Vous reconnaissez quelques mots — c''est une langue que vous avez un peu étudiée à l''école.)", "choices": [{"text": "(Offer to help translate, even with limited knowledge.)", "text_fr": "(Propose d''aider à traduire, même avec des connaissances limitées.)", "next": "n3"}]}, "n2b": {"speaker": "nurse", "text": "Oh, that would be incredibly helpful, thank you! We''re really struggling to understand her.", "text_fr": "Oh, ce serait incroyablement utile, merci ! On a vraiment du mal à la comprendre.", "choices": [{"text": "I only know a little of the language, but I''ll try my best.", "text_fr": "Je connais seulement un peu la langue, mais je vais faire de mon mieux.", "next": "n3"}]}, "n3": {"speaker": "patient", "text": "(Speaking anxiously in her language, clearly in pain and scared.)", "text_fr": "(Parlant anxieusement dans sa langue, clairement en douleur et effrayée.)", "choices": [{"text": "(Try to catch key words like ''pain'' or body parts.)", "text_fr": "(Essaie de saisir des mots clés comme ''douleur'' ou des parties du corps.)", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(You catch the word for ''stomach'' and gesture for her to point to where it hurts.)", "text_fr": "(Vous saisissez le mot pour ''estomac'' et lui faites signe de montrer où ça fait mal.)", "choices": [{"text": "(Point to your own stomach and ask ''here?'' in her language.)", "text_fr": "(Pointe ton propre estomac et demande ''ici ?'' dans sa langue.)", "next": "n5"}]}, "n5": {"speaker": "patient", "text": "(Nods, pointing to her lower right side, wincing in pain.)", "text_fr": "(Hoche la tête, pointant son côté inférieur droit, grimaçant de douleur.)", "choices": [{"text": "(Relay to the nurse) She''s pointing to her lower right stomach area.", "text_fr": "(Relaie à l''infirmière) Elle pointe sa zone d''estomac inférieure droite.", "next": "n6"}]}, "n6": {"speaker": "nurse", "text": "That''s really helpful, thank you. Can you ask how long she''s had this pain?", "text_fr": "C''est vraiment utile, merci. Vous pouvez demander depuis quand elle a cette douleur ?", "choices": [{"text": "(Try to mime ''how long'' with hand gestures and simple words.)", "text_fr": "(Essaie de mimer ''depuis combien de temps'' avec des gestes et des mots simples.)", "next": "n7"}, {"text": "(Use a translation app on your phone to help communicate more precisely.)", "text_fr": "(Utilise une appli de traduction sur ton téléphone pour communiquer plus précisément.)", "next": "n7b"}]}, "n7": {"speaker": "patient", "text": "(Holds up three fingers, then points to a clock, trying to communicate hours.)", "text_fr": "(Lève trois doigts, puis pointe une horloge, essayant de communiquer des heures.)", "choices": [{"text": "(Relay to the nurse) I think she means about three hours.", "text_fr": "(Relaie à l''infirmière) Je pense qu''elle veut dire environ trois heures.", "next": "n8"}]}, "n7b": {"speaker": "you_thought", "text": "(The translation app helps bridge the gap much more precisely.)", "text_fr": "(L''appli de traduction aide à combler le fossé bien plus précisément.)", "choices": [{"text": "(Read the translated question aloud to her.)", "text_fr": "(Lis la question traduite à voix haute pour elle.)", "next": "n8"}]}, "n8": {"speaker": "nurse", "text": "That''s extremely helpful, thank you both. This sounds like it could be appendicitis.", "text_fr": "C''est extrêmement utile, merci à vous deux. Ça ressemble à une possible appendicite.", "choices": [{"text": "Should I stay to help translate a bit more, or would that be too much?", "text_fr": "Je devrais rester pour aider à traduire un peu plus, ou ce serait trop ?", "next": "n9"}, {"text": "I''m happy to stay as long as it''s helpful for her.", "text_fr": "Je suis content de rester tant que c''est utile pour elle.", "next": "n9"}]}, "n9": {"speaker": "nurse", "text": "If you''re comfortable, staying a bit longer would really help ease her anxiety too.", "text_fr": "Si vous êtes à l''aise, rester un peu plus longtemps aiderait vraiment à apaiser son anxiété aussi.", "choices": [{"text": "Of course, I don''t mind at all.", "text_fr": "Bien sûr, ça ne me dérange pas du tout.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(You stay by her side, offering small reassurances as the doctor arrives.)", "text_fr": "(Vous restez à ses côtés, offrant de petits mots rassurants alors que le médecin arrive.)", "choices": [{"text": "(Try to comfort her with a calm tone and simple gestures.)", "text_fr": "(Essaie de la réconforter avec un ton calme et des gestes simples.)", "next": "n11"}]}, "n11": {"speaker": "patient", "text": "(Visibly calmer now, gives a small, grateful smile toward you.)", "text_fr": "(Visiblement plus calme maintenant, vous adresse un petit sourire reconnaissant.)", "choices": [{"text": "(Smile back reassuringly, glad to have helped.)", "text_fr": "(Souris en retour de façon rassurante, content d''avoir aidé.)", "next": "n12"}]}, "n12": {"speaker": "doctor", "text": "Thank you so much for your help today — it made a real difference for her care.", "text_fr": "Merci beaucoup pour votre aide aujourd''hui — ça a vraiment fait la différence pour ses soins.", "choices": [{"text": "I''m just glad I could help, even with my limited language skills.", "text_fr": "Je suis juste content d''avoir pu aider, même avec mes compétences linguistiques limitées.", "next": "end_helped"}]}, "end_helped": {"speaker": "nurse", "text": "Limited or not, it truly mattered today. Thank you again.", "text_fr": "Limitées ou pas, ça a vraiment compté aujourd''hui. Merci encore.", "end": true, "ending_label": "Un pont linguistique qui a changé la donne 🗣️🏥💙"}}}'::jsonb, is_playable = true
where title = 'Gérer une urgence avec la barrière de la langue'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
